function blocked(x,z){return !inBounds(x,z,15)||colliders.some(b=>x>b.minx-1&&x<b.maxx+1&&z>b.minz-1&&z<b.maxz+1&&inside(x,z,b.p))}
function moveWalk(dx,dz){if(!blocked(walkPos.x+dx,walkPos.z))walkPos.x+=dx;if(!blocked(walkPos.x,walkPos.z+dz))walkPos.z+=dz}
function walkAt(x,z){if(blocked(x,z)){let best=null;for(const r of city.roads){if(['trunk','secondary'].includes(r.kind))continue;for(const p of r.p){const d=Math.hypot(p[0]-x,p[1]-z);if((!best||d<best.d)&&!blocked(...p))best={p,d}}}if(best){x=best.p[0];z=best.p[1]}}walkPos.set(x,elev(x,z)+1.75,z)}
